import fs from 'node:fs/promises';import crypto from 'node:crypto';
import {RemoteD1Database} from '../runner/report2-d1-adapter.mjs';
import {loadDailyUsageAggregate,evaluateDailyReservationBudget,reserveRunBudget,finalizeRunUsage} from '../runner/d1-preaction-budget-guard.mjs';
const saved=JSON.parse(await fs.readFile('checkpoints/native-source-batch-tests-37799119119/natural-sent-task-read.json')),db=new RemoteD1Database(process.env.REPORT2_D1_BRIDGE_URL,process.env.REPORT2_D1_BRIDGE_TOKEN),now=Date.now(),reservation={rows_read:1500,rows_written:20},id='ORIGINAL_LIFECYCLE:'+process.env.GITHUB_RUN_ID;
const out={schema:'EXACT_ORIGINAL_SENT_LIFECYCLE_AND_TRIGGER_CLOCKS_V1',head:process.env.GITHUB_SHA,cloud_run:process.env.GITHUB_RUN_ID,read_ts:now,sourceHTTP:0,MAIN:0,Telegram:0,source_clocks_refreshed:false,task_writes:0,cases:[]};
out.admission=evaluateDailyReservationBudget({daily:await loadDailyUsageAggregate(db,now),nextReservation:reservation,maxDailyReads:3500000,maxDailyWrites:70000});
if(out.admission.allowed){await reserveRunBudget(db,{reservationId:id,now,reservation});try{for(const c of saved.cases){
 const lifecycle=await db.prepare('SELECT l.contract,l.direction,l.wave_id,l.rules_version,l.status,l.reason,l.observation_ts,l.valid_until_ts,l.updated_ts,b.publication_id,b.run_id,b.snapshot_id,b.analytical_fingerprint,b.lifecycle_event FROM v3_dispatch_publication_binding_shadow b JOIN v3_user_lifecycle_shadow l ON l.contract=b.contract_code AND l.direction=b.direction AND l.wave_id=b.wave_id AND l.rules_version=b.rules_version WHERE b.publication_id=?1 AND b.run_id=?2 AND b.snapshot_id=?3 AND b.analytical_fingerprint=?4 LIMIT 1').bind(c.publication_id,c.run_id,c.snapshot_id,c.analytical_fingerprint).first();
 const publication=await db.prepare('SELECT publication_id,contract_code,direction,wave_id,run_id,snapshot_id,observed_ts,valid_until_ts,analytical_fingerprint,canonical_json,actionability_status FROM canonical_publication_shadow WHERE publication_id=?1 AND run_id=?2 AND snapshot_id=?3 AND analytical_fingerprint=?4 LIMIT 1').bind(c.publication_id,c.run_id,c.snapshot_id,c.analytical_fingerprint).first();
 const canonical=JSON.parse(publication.canonical_json),original_row_exact=lifecycle?.observation_ts===c.observed_ts;
 out.cases.push({...c,lifecycle,publication,canonical_contract:canonical.metadata?.contract,canonical_keys:Object.keys(canonical),original_row_exact,lifecycle_expires_before_due:original_row_exact&&lifecycle.valid_until_ts<c.original_trigger.next_recheck_ts,lifecycle_active_at_near_missed_job:original_row_exact&&lifecycle.valid_until_ts>1791459975399});
 const u=db.usageSnapshot();if(u.unknown_ops||u.rows_read>1300||u.rows_written>18||u.requests>12)throw Error('BOUNDED_READ_EXCEEDED');
}out.status='EXACT_ORIGINAL_LIFECYCLE_CLOCKS_READ';}catch(e){out.status='READ_FAILED';out.error=String(e.message).slice(0,200);}finally{out.finalized_usage=await finalizeRunUsage(db,{reservationId:id,sourceRunId:process.env.GITHUB_RUN_ID,usage:db.usageSnapshot()});}}else out.status='D1_ADMISSION_BLOCKED';
out.d1_usage=db.usageSnapshot();await fs.mkdir('audit-output',{recursive:true});await fs.writeFile('audit-output/original-lifecycle-trigger-clocks.json',JSON.stringify(out,null,2)+'\n');console.log(JSON.stringify({status:out.status,cases:out.cases.map(c=>({contract:c.contract,original_row_exact:c.original_row_exact,canonical_contract:c.canonical_contract,lifecycle:c.lifecycle,lifecycle_expires_before_due:c.lifecycle_expires_before_due})),D1:out.d1_usage,error:out.error}));if(out.status!=='EXACT_ORIGINAL_LIFECYCLE_CLOCKS_READ')process.exitCode=1;
